mapper.update:
UPDATE funding
SET view_count = view_count + 1
WHERE funding_id = #{fundingId}

mapper.select:
SELECT COUNT(*)
FROM donation_like
WHERE donation_id = #{donationId}
  AND user_id = #{userId}
    LIMIT 1

mapper.delete:
DELETE FROM donation_like
WHERE donation_id = #{donationId}
  AND user_id = #{userId}
